package net.minecraft.world.entity.ai.navigation;import net.minecraft.world.entity.Entity;public class PathNavigation{public int moves,stops;public double speed;public boolean moveTo(Entity e,double s){moves++;speed=s;return true;}public double x,y,z;public boolean moveTo(double x,double y,double z,double s){moves++;speed=s;this.x=x;this.y=y;this.z=z;return true;}public void stop(){stops++;}}